package com.example.groomingresearchdemo.inspection

import com.example.groomingresearchdemo.AppConstants
import com.example.groomingresearchdemo.inspection.candidate.NodeSample

/**
 * Traverses one accessibility tree into a flat list of [NodeSample]s.
 *
 * THIS IS A SECOND PASS, AND THAT IS DELIBERATE
 * [StructuralInspector] still runs first, unchanged, and still produces the R1-R8 compatibility
 * numbers. Reusing its output would have been tidier, but it would also have meant that the
 * evidence underpinning the compatibility report was generated by code that had since been modified
 * for a different purpose. Keeping the two passes separate means the compatibility claim stays
 * byte-for-byte reproducible while the extraction claim is measured on its own terms. The cost is
 * one extra traversal of a tree that is already in memory; it is synchronous, bounded, and it ends
 * when the one-shot inspection ends.
 *
 * WHAT IT DEFENSIBLY HANDLES
 *  - a node reached twice is sampled once (platform node id, else object identity);
 *  - a property that throws costs that property, not the node;
 *  - a subtree whose children vanish mid-traversal is counted, not crashed;
 *  - the node cap truncates and says so, rather than reporting a partial tree as a whole one;
 *  - no AccessibilityNodeView reference outlives the returned list: everything downstream is values.
 */
class MessageLevelTraverser(
    private val maxNodes: Int = AppConstants.MAX_TRAVERSAL_NODES,
) {

    /**
     * @param viewport the visible window rectangle used to detect clipped rows; null when the
     *   framework would not give one, which turns "partially visible" into "unknown" instead of
     *   silently claiming full visibility.
     */
    fun traverse(
        root: AccessibilityNodeView?,
        viewport: NodeBounds? = null,
    ): Traversal {
        if (root == null) return Traversal.empty(mutationNote = "root unavailable")

        val samples = ArrayList<NodeSample>(64)
        val seenIds = HashSet<Long>()
        val seenByIdentity = HashMap<AccessibilityNodeView, Boolean>()
        val notes = mutableListOf<String>()

        var duplicatesSuppressed = 0
        var nodesLostDuringTraversal = 0
        var nodesVisited = 0
        var truncated = false

        val queue = ArrayDeque<Pair<AccessibilityNodeView, Int>>()
        queue.addLast(root to 1)
        remember(root, seenIds, seenByIdentity)

        while (queue.isNotEmpty()) {
            if (nodesVisited >= maxNodes) {
                truncated = true
                addNote(notes, "Extraction stopped at the $maxNodes node cap; the sample is partial.")
                break
            }
            val (node, depth) = queue.removeFirst()
            nodesVisited++

            val bounds = runCatching { node.boundsInScreen() }.getOrNull()
            // ONE read per property. The framework is allowed to hand back a different node text on
            // the next call, so `text` and `hasText` must come from the same instant or a sample can
            // report text present while carrying none.
            val rawText = runCatching { node.text() }.getOrNull()
            val rawDescription = runCatching { node.contentDescription() }.getOrNull()
            val declaredChildren = runCatching { node.childCount() }.getOrNull()
            val sample = NodeSample(
                nodeId = runCatching { node.nodeId() }.getOrNull(),
                parentNodeId = runCatching { node.parent()?.nodeId() }.getOrNull(),
                depth = depth,
                className = runCatching { node.className()?.toString() }.getOrNull(),
                text = rawText?.toString()?.trim()?.takeIf { it.isNotEmpty() },
                hasText = rawText != null,
                hasContentDescription = rawDescription != null,
                isClickable = runCatching { node.isClickable() }.getOrDefault(false),
                isScrollable = runCatching { node.isScrollable() }.getOrDefault(false),
                isVisibleToUser = runCatching { node.isVisibleToUser() }.getOrNull(),
                bounds = bounds,
                childCount = declaredChildren ?: 0,
                aggregatesDescendantText = runCatching { node.aggregatesDescendantText() }.getOrDefault(false),
            )
            samples.add(sample)

            if (declaredChildren == null) {
                // The framework would not even say how many children this node has, so everything
                // under it is unknown. Counted as a lost subtree rather than silently treated as a
                // leaf: a node that refuses enumeration is not evidence that a screen is small.
                nodesLostDuringTraversal++
            }
            val childCount = declaredChildren ?: 0
            var enqueued = 0
            for (index in 0 until childCount) {
                val child = try {
                    node.getChild(index)
                } catch (t: Throwable) {
                    null
                }
                if (child == null) {
                    if (enqueued == 0 && index == 0) {
                        // The node claimed children and then handed back nothing at all. On a live
                        // tree that is the signature of the hierarchy changing underneath us.
                        nodesLostDuringTraversal++
                    }
                    continue
                }
                enqueued++
                val id = runCatching { child.nodeId() }.getOrNull()
                val alreadySeen = if (id != null) !seenIds.add(id)
                else seenByIdentity.put(child, true) != null
                if (alreadySeen) {
                    duplicatesSuppressed++
                    continue
                }
                queue.addLast(child to depth + 1)
            }
            if (enqueued in 1 until childCount) nodesLostDuringTraversal++
        }

        if (nodesLostDuringTraversal > 0) {
            addNote(
                notes,
                "$nodesLostDuringTraversal node(s) reported children that were not retrievable; " +
                    "the tree changed during inspection.",
            )
        }
        if (viewport == null) {
            addNote(notes, "Viewport rectangle unavailable; partial-visibility could not be assessed.")
        }

        return Traversal(
            samples = samples,
            nodesVisited = nodesVisited,
            duplicatesSuppressed = duplicatesSuppressed,
            nodesLostDuringTraversal = nodesLostDuringTraversal,
            truncated = truncated,
            viewport = viewport,
            notes = notes,
        )
    }

    private fun remember(
        node: AccessibilityNodeView,
        ids: MutableSet<Long>,
        identity: HashMap<AccessibilityNodeView, Boolean>,
    ) {
        val id = runCatching { node.nodeId() }.getOrNull()
        if (id != null) ids.add(id) else identity.put(node, true)
    }

    private fun addNote(notes: MutableList<String>, note: String) {
        if (notes.size < AppConstants.MAX_NOTES && note !in notes) notes.add(note)
    }
}

/** Raw result of one extraction traversal, before any message judgement is made. */
data class Traversal(
    val samples: List<NodeSample>,
    val nodesVisited: Int,
    val duplicatesSuppressed: Int,
    val nodesLostDuringTraversal: Int,
    val truncated: Boolean,
    val viewport: NodeBounds?,
    val notes: List<String>,
) {
    val mutatedDuringInspection: Boolean get() = nodesLostDuringTraversal > 0

    /** Counts and flags only. The generated version would print up to `maxNodes` sampled texts. */
    override fun toString(): String =
        "Traversal(samples=${samples.size}, nodesVisited=$nodesVisited, " +
            "duplicatesSuppressed=$duplicatesSuppressed, nodesLostDuringTraversal=$nodesLostDuringTraversal, " +
            "truncated=$truncated, viewport=$viewport, notes=$notes)"

    companion object {
        fun empty(mutationNote: String): Traversal = Traversal(
            samples = emptyList(),
            nodesVisited = 0,
            duplicatesSuppressed = 0,
            nodesLostDuringTraversal = 0,
            truncated = false,
            viewport = null,
            notes = listOf(mutationNote),
        )
    }
}
